            }
        });
        int[] ans = new int[k];
        for (int i = 0; i < k; i++) ans[i] = rows[i][1];
        return ans;
    }

    private int countOnes(int[] row) {
        int left = 0, right = row.length; // search for first 0
        while (left < right) {
